@IsLocalization.mk'_surjective : ∀ {R : Type u_1} [inst : CommSemiring R] (M : Submonoid R) {S : Type u_2}
  [inst_1 : CommSemiring S] [inst_2 : Algebra R S] [inst_3 : IsLocalization M S],
  Function.Surjective fun x =>
    match x with
    | (r, m) => IsLocalization.mk' S r m
@IsLocalization.eq_iff_exists : ∀ {R : Type u_1} [inst : CommSemiring R] (M : Submonoid R) (S : Type u_2)
  [inst_1 : CommSemiring S] [inst_2 : Algebra R S] [IsLocalization M S] {x y : R},
  (algebraMap R S) x = (algebraMap R S) y ↔ ∃ c, ↑c * x = ↑c * y
@IsLocalization.mk'_eq_iff_eq : ∀ {R : Type u_1} [inst : CommSemiring R] {M : Submonoid R} {S : Type u_2}
  [inst_1 : CommSemiring S] [inst_2 : Algebra R S] [inst_3 : IsLocalization M S] {x₁ x₂ : R} {y₁ y₂ : ↥M},
  IsLocalization.mk' S x₁ y₁ = IsLocalization.mk' S x₂ y₂ ↔ (algebraMap R S) (↑y₂ * x₁) = (algebraMap R S) (↑y₁ * x₂)
inferInstance : Finite Gal(L/K)

